import { MakeLogicType, actions, connect, kea, path, reducers, selectors } from 'kea'

import { getBackendHost } from 'lib/oauth/oauthClient'
import { teamLogic } from 'scenes/teamLogic'

import type { TeamType } from '~/types'

import { mcpAnalyticsSetupPrompt } from './mcpAnalyticsSetupPrompt'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mcpAnalyticsSetupLogicValues {
    currentTeam: TeamType | null // teamLogic
    agentPromptOpen: boolean
    agentPrompt: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface mcpAnalyticsSetupLogicActions {
    setAgentPromptOpen: (open: boolean) => { open: boolean }
}

export type mcpAnalyticsSetupLogicType = MakeLogicType<mcpAnalyticsSetupLogicValues, mcpAnalyticsSetupLogicActions>

export const mcpAnalyticsSetupLogic = kea<mcpAnalyticsSetupLogicType>([
    path(['products', 'mcp_analytics', 'frontend', 'emptyState', 'mcpAnalyticsSetupLogic']),
    connect(() => ({ values: [teamLogic, ['currentTeam']] })),
    actions({ setAgentPromptOpen: (open: boolean) => ({ open }) }),
    reducers({ agentPromptOpen: [false, { setAgentPromptOpen: (_, { open }) => open }] }),
    selectors({
        agentPrompt: [
            (s) => [s.currentTeam],
            (team: TeamType | null): string | null =>
                team ? mcpAnalyticsSetupPrompt(team.id, getBackendHost() || window.location.origin) : null,
        ],
    }),
])
